SELECT PRIORITY AS groupKey, COUNT(*) AS count FROM TASK WHERE STATUS <> 'DELETED' AND USER_ID = #{userId} AND DUE_DATE >= TO_DATE(#{startDate}, 'YYYY-MM-DD') AND DUE_DATE < TO_DATE(#{endDate}, 'YYYY-MM-DD') + 1
AND CATEGORY_ID = #{categoryId}
GROUP BY PRIORITY ORDER BY COUNT(*) DESC

SELECT TC.TITLE AS categoryName, COUNT(*) AS totalCount, SUM( CASE WHEN T.TASK_STATUS = 'DONE' THEN 1 ELSE 0 END ) AS doneCount FROM TASK T JOIN TASK_CATEGORY TC ON T.CATEGORY_ID = TC.CATEGORY_ID WHERE T.STATUS <> 'DELETED' AND T.USER_ID = #{userId} AND T.DUE_DATE >= TO_DATE(#{startDate}, 'YYYY-MM-DD') AND T.DUE_DATE < TO_DATE(#{endDate}, 'YYYY-MM-DD') + 1 AND TC.STATUS <> 'DELETED'
AND T.CATEGORY_ID = #{categoryId}
GROUP BY TC.TITLE ORDER BY COUNT(*) DESC

SELECT T.PRIORITY AS priority, COUNT(*) AS totalCount, SUM( CASE WHEN T.TASK_STATUS = 'DONE' THEN 1 ELSE 0 END ) AS doneCount FROM TASK T WHERE T.STATUS <> 'DELETED' AND T.USER_ID = #{userId} AND T.DUE_DATE >= TO_DATE(#{startDate}, 'YYYY-MM-DD') AND T.DUE_DATE < TO_DATE(#{endDate}, 'YYYY-MM-DD') + 1
AND T.CATEGORY_ID = #{categoryId}
GROUP BY T.PRIORITY ORDER BY CASE T.PRIORITY WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2 WHEN 'LOW' THEN 3 ELSE 4 END
